<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.min.js"></script>
<script>
$(function(){let slide=0,slides=$('.hero-slide');setInterval(()=>{slides.eq(slide).removeClass('active');slide=(slide+1)%slides.length;slides.eq(slide).addClass('active')},6500);const msgs=['Reading your brief.','Checking spaces and functions.','Checking plot proportions.','Planning circulation.','Preparing the editable model.'];let aiPlan=null,originalPlan=null,selected=-1;
function esc(v){return $('<div>').text(v==null?'':v).html()}
function normalizePlan(p){let rooms=Array.isArray(p.rooms)?p.rooms:[];let cols=Math.max(2,Math.ceil(Math.sqrt(rooms.length||1)));rooms=rooms.map((r,i)=>({name:r.name||'Space '+(i+1),width:Math.max(1,Number(r.width)||3),depth:Math.max(1,Number(r.depth)||3),type:r.type||'other',x:20+(i%cols)*170,y:20+Math.floor(i/cols)*125}));return {...p,rooms}}
function renderEditor(){if(!aiPlan)return;let board=$('#planBoard');board.find('.room').remove();let rooms=aiPlan.rooms||[];rooms.forEach((r,i)=>{let px=Math.max(90,Math.min(220,r.width*28)),py=Math.max(65,Math.min(130,r.depth*24));let el=$(`<div class="room ${i===selected?'selected':''}" data-i="${i}"><div><strong>${esc(r.name)}</strong><em>${r.width.toFixed(1)} × ${r.depth.toFixed(1)} m</em></div></div>`);el.css({left:r.x+'px',top:r.y+'px',width:px+'px',height:py+'px'});el.on('mousedown touchstart',function(ev){selected=i;renderEditor();let e=ev.originalEvent.touches?ev.originalEvent.touches[0]:ev.originalEvent;let sx=e.clientX,sy=e.clientY,ox=r.x,oy=r.y;function move(me){let q=me.touches?me.touches[0]:me;r.x=Math.max(5,Math.min(730,ox+q.clientX-sx));r.y=Math.max(5,Math.min(540,oy+q.clientY-sy));renderEditor();}function up(){document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);document.removeEventListener('touchmove',move);document.removeEventListener('touchend',up);render3D();}document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);document.addEventListener('touchmove',move,{passive:false});document.addEventListener('touchend',up);ev.preventDefault()});board.append(el)});renderList();syncEditor();render3D()}
function renderList(){$('#editList').html((aiPlan.rooms||[]).map((r,i)=>`<button type="button" class="edit-item text-start ${i===selected?'active':''}" data-i="${i}"><strong>${esc(r.name)}</strong><div class="note">${r.width.toFixed(1)} × ${r.depth.toFixed(1)} m</div></button>`).join(''));$('.edit-item').on('click',function(){selected=Number($(this).data('i'));renderEditor()})}
function syncEditor(){if(selected<0||!aiPlan.rooms[selected]){$('#emptyEditor').removeClass('d-none');$('#roomEditor').addClass('d-none');return}let r=aiPlan.rooms[selected];$('#emptyEditor').addClass('d-none');$('#roomEditor').removeClass('d-none');$('#editName').val(r.name);$('#editW').val(r.width);$('#editD').val(r.depth)}
$('#applyEdit').on('click',function(){if(selected<0)return;let r=aiPlan.rooms[selected];r.name=$('#editName').val().trim()||r.name;r.width=Math.max(1,Number($('#editW').val())||r.width);r.depth=Math.max(1,Number($('#editD').val())||r.depth);renderEditor()});
$('#resetPlan').on('click',function(){aiPlan=normalizePlan(JSON.parse(JSON.stringify(originalPlan)));selected=-1;renderEditor()});
function renderSummary(p){$('#rTitle').text(p.title||'Architectural Concept');$('#rSummary').text(p.summary||'');$('#houseW').text(Number(p.house_width||0).toFixed(2));$('#houseD').text(Number(p.house_depth||0).toFixed(2));$('#roomCount').text((p.rooms||[]).length);$('#outside').text(p.outside_preview||'The exterior follows the same footprint, circulation, entrance, daylight and roof logic as the plan.');$('#dimensions').html((p.rooms||[]).map(r=>`<div class="stat-line"><span>${esc(r.name)}</span><strong>${Number(r.width).toFixed(1)} × ${Number(r.depth).toFixed(1)}m</strong></div>`).join(''))}
function render3D(){let c=document.getElementById('threeCanvas');if(!c||!window.THREE||!aiPlan)return;if(window.rm3d)window.rm3d.dispose();let renderer=new THREE.WebGLRenderer({canvas:c,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));let scene=new THREE.Scene();scene.background=new THREE.Color(0x151a16);let camera=new THREE.PerspectiveCamera(42,c.clientWidth/Math.max(c.clientHeight,1),.1,1000);camera.position.set(18,18,22);let amb=new THREE.HemisphereLight(0xffffff,0x3b4638,2.1);scene.add(amb);let sun=new THREE.DirectionalLight(0xffffff,2.2);sun.position.set(12,25,10);scene.add(sun);let group=new THREE.Group();let rooms=aiPlan.rooms||[];let maxX=Math.max(...rooms.map(r=>r.x+r.width*20),500),maxY=Math.max(...rooms.map(r=>r.y+r.depth*20),400);let scale=0.06;rooms.forEach((r,i)=>{let w=Math.max(1,r.width),d=Math.max(1,r.depth),h=r.type==='courtyard'?.35:2.8;let geo=new THREE.BoxGeometry(w,h,d);let mat=new THREE.MeshStandardMaterial({color:r.type==='courtyard'?0x788a6f:(i%2?0xc9c1b0:0xe1d9c9),roughness:.78,metalness:.05});let m=new THREE.Mesh(geo,mat);m.position.set((r.x-maxX/2)*scale+w/2, h/2,(r.y-maxY/2)*scale+d/2);group.add(m)});scene.add(group);let ground=new THREE.Mesh(new THREE.PlaneGeometry(60,60),new THREE.MeshStandardMaterial({color:0x293129,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.02;scene.add(ground);function resize(){let w=c.clientWidth,h=c.clientHeight||610;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}resize();window.addEventListener('resize',resize);let dragging=false,last={x:0,y:0};c.onmousedown=e=>{dragging=true;last={x:e.clientX,y:e.clientY}};window.addEventListener('mouseup',()=>dragging=false);window.addEventListener('mousemove',e=>{if(!dragging)return;let dx=e.clientX-last.x,dy=e.clientY-last.y;group.rotation.y+=dx*.01;camera.position.y=Math.max(6,Math.min(35,camera.position.y-dy*.05));last={x:e.clientX,y:e.clientY}});c.onwheel=e=>{camera.position.multiplyScalar(e.deltaY>0?1.06:.94);camera.position.y=Math.max(5,Math.min(45,camera.position.y))};function animate(){renderer.render(scene,camera);requestAnimationFrame(animate)}animate();$('#camIso').off('click').on('click',()=>{camera.position.set(18,18,22);group.rotation.y=0});$('#camTop').off('click').on('click',()=>{camera.position.set(0,32,.01);group.rotation.y=0});$('#camFront').off('click').on('click',()=>{camera.position.set(0,8,28);group.rotation.y=0});window.rm3d={dispose:()=>{renderer.dispose();window.removeEventListener('resize',resize)}}}
$('#update3d').on('click',()=>{render3D();$('html,body').animate({scrollTop:$('#threeCanvas').offset().top-100},500)});
function showResults(){renderSummary(aiPlan);$('#results').fadeIn(400);renderEditor();$('html,body').animate({scrollTop:$('#results').offset().top-65},650)}
function generateExterior(p){let data={house_width:p.house_width,house_depth:p.house_depth,plot_width:$('[name=plot_width]').val(),plot_depth:$('[name=plot_depth]').val(),road_side:$('[name=road_side]').val(),style:$('[name=style]').val(),rooms:p.rooms,outside_preview:p.outside_preview||'',brief:$('[name=brief]').val()};$.ajax({url:'api/exterior.php',method:'POST',contentType:'application/json',data:JSON.stringify(data),dataType:'json',timeout:150000}).done(function(r){if(r.ok&&r.image_url){$('#outside').append('<div class="note mt-3">AI exterior image is also available from the original generation pipeline.</div>')}})}
$('#plannerForm').on('submit',function(e){e.preventDefault();let data={};$(this).serializeArray().forEach(x=>data[x.name]=x.value);$('#loading').css('display','flex');let i=0,timer=setInterval(()=>$('#loadingText').text(msgs[++i%msgs.length]),1100);$('.btn-text').addClass('d-none');$('.spinner-border').removeClass('d-none');$('#clarify').addClass('d-none').empty();$.ajax({url:'api/generate.php',method:'POST',contentType:'application/json',data:JSON.stringify(data),dataType:'json',timeout:90000}).done(function(res){if(!res.ok){alert(res.message||'AI service haikupatikana.');return}let p=res.plan||{};if(p.needs_clarification){$('#clarify').removeClass('d-none').html('<strong>AI inahitaji clarification:</strong><ul class="mb-0 mt-2">'+(p.questions||[]).map(q=>'<li>'+esc(q)+'</li>').join('')+'</ul>');$('#results').fadeIn(350);$('html,body').animate({scrollTop:$('#results').offset().top-65},600);return}originalPlan=normalizePlan(JSON.parse(JSON.stringify(p)));aiPlan=normalizePlan(JSON.parse(JSON.stringify(p)));selected=-1;showResults();generateExterior(p)}).fail(function(xhr){let m='Imeshindikana kuwasiliana na AI service.';try{let j=JSON.parse(xhr.responseText);if(j.message)m=j.message}catch(e){}alert(m)}).always(function(){clearInterval(timer);$('#loading').hide();$('.btn-text').removeClass('d-none');$('.spinner-border').addClass('d-none')})});
});
</script>
</body></html>